      relatedTopics: ["Acute kidney injury", "Hydronephrosis", "Urinary retention", "Benign prostatic hyperplasia", "Kidney stones", "Urosepsis"],
      causalLinks: ["Urine-flow obstruction -> higher tubular pressure -> opposition to glomerular filtration -> AKI", "Persistent pressure and inflammation -> tubular atrophy and fibrosis -> CKD", "Infected obstruction -> trapped infected urine -> rapid sepsis risk", "Decompression after prolonged obstruction -> salt and water diuresis -> hypovolemia and electrolyte loss"],
      sourceKeys: ["kdigo-aki-2012", "niddk-kidney-function"],
      tags: ["postrenal AKI", "obstruction", "hydronephrosis", "urinary retention", "postobstructive diuresis"]
