  cards.forEach((incoming) => {
    const canonical = normalize(incoming.name || incoming.title);
    const index = pathology.diseases.findIndex((entry) =>
      [entry.name, entry.title].map(normalize).filter(Boolean).includes(canonical)
    );
    const existing = index >= 0 ? pathology.diseases[index] : {};
    const merged = {
      ...existing,
      ...incoming,
      aliases: unique(incoming.aliases || []),
      abbreviations: unique(incoming.abbreviations || []),
      tags: unique(["frontier-wave25", "renal causal reasoning", "strict why closure", ...(incoming.tags || [])])
    };
    delete merged.replaceExistingAliases;
    if (index >= 0) pathology.diseases[index] = merged;
    else pathology.diseases.push(merged);
  });

  /* Remove legacy expansion pollution: AV means arteriovenous here, never atrioventricular. */
  const avCanonicalNames = new Set(["av fistula thrombosis", "av fistula infection"]);
  pathology.diseases = pathology.diseases.map((entry) => {
    const key = normalize(entry.name || entry.title);
    if (!avCanonicalNames.has(key)) return entry;
    return {
      ...entry,
      aliases: (entry.aliases || []).filter((alias) => !/atrioventricular|^av\s*:\s*atrioventricular$/i.test(String(alias || ""))),
      abbreviations: (entry.abbreviations || []).filter((alias) => !/atrioventricular/i.test(String(alias || ""))),
      tags: (entry.tags || []).filter((tag) => !/atrioventricular/i.test(String(tag || "")))
    };
  });

